COLLECTOR_SOURCE="def collect(state,credential):\n    capture=state['capture'];streams={};process=None;failure=None;payload=bytearray(credential)+state['source'];credential=b''\n    durable={}\n    def retain(stream,part):\n        record=durable[stream];record['pending'].extend(part)\n        while len(record['pending'])>=CHUNK:\n            raw=bytes(record['pending'][:CHUNK]);del record['pending'][:CHUNK]\n            name=record['name']+'-'+str(len(record['chunks']))+'.private'\n            pin=capture.create(name,raw);record['chunks'].append({'name':name,'pin':pin})\n        streams[stream].extend(part)\n    def finish(name,stream):\n        if stream is None:\n            archive(capture,name,b'');return\n        record=durable[stream]\n        if record['pending']:\n            child=name+'-'+str(len(record['chunks']))+'.private';pin=capture.create(child,bytes(record['pending']))\n            record['chunks'].append({'name':child,'pin':pin});record['pending'].clear()\n        raw=bytes(streams[stream]);manifest={'bytes':len(raw),'sha256':digest(raw),'chunks':record['chunks']}\n        capture.create(name+'-manifest.json',encoded(manifest))\n    try:\n        process=subprocess.Popen(state['argv'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)\n        streams={process.stdout:bytearray(),process.stderr:bytearray()}\n        durable={stream:{'name':name,'pending':bytearray(),'chunks':[]} for name,stream in [('stdout',process.stdout),('stderr',process.stderr)]}\n        deadline=time.monotonic()+1250\n        capture.create('handle.json',encoded({'pid':process.pid,'started':time.time(),'deadlineSeconds':1250}))\n        os.set_blocking(process.stdin.fileno(),False);opened=list(streams);offset=0;writer=process.stdin\n        while opened or writer is not None:\n            remaining=deadline-time.monotonic()\n            if remaining<=0:raise ValueError('baseline_local_collection_timeout')\n            ready,writable,_=select.select(opened,[writer] if writer is not None else [],[],min(remaining,1))\n            if writable:\n                end=min(offset+65536,len(payload));sent=os.write(writer.fileno(),payload[offset:end])\n                if sent<=0:raise ValueError('baseline_stdin_transfer_unknown')\n                payload[offset:offset+sent]=b'\\0'*sent;offset+=sent\n                if offset==len(payload):writer.close();writer=None;payload.clear()\n            for stream in ready:\n                part=os.read(stream.fileno(),65536)\n                if not part:opened.remove(stream);continue\n                retain(stream,part)\n                if sum(map(len,streams.values()))>STREAM_LIMIT:raise ValueError('baseline_local_collection_limit')\n        process.wait(timeout=max(.01,deadline-time.monotonic()))\n    except Exception as error:failure=type(error).__name__\n    finally:\n        payload.clear()\n        if process is not None:\n            if process.stdin is not None and not process.stdin.closed:process.stdin.close()\n            if process.poll()is None:process.kill();process.wait(timeout=5)\n            # Retain bytes already in both pipes after a timeout or writer loss.\n            remaining_streams=[stream for stream in streams if not stream.closed]\n            drain_deadline=time.monotonic()+5\n            while remaining_streams and time.monotonic()<drain_deadline:\n                ready,_,_=select.select(remaining_streams,[],[],.1)\n                for stream in ready:\n                    part=os.read(stream.fileno(),65536)\n                    if not part:remaining_streams.remove(stream);continue\n                    retain(stream,part)\n                    if sum(map(len,streams.values()))>STREAM_LIMIT:failure='baseline_local_collection_limit';remaining_streams=[];break\n        for name,stream in [('stdout',getattr(process,'stdout',None)),('stderr',getattr(process,'stderr',None))]:\n            finish(name,stream)\n            if stream is not None:stream.close()\n        capture.create('exit.json',encoded({'returncode':process.returncode if process is not None else None,'failure':failure}))\n        os.fsync(capture.fd)\n    if process is None or failure is not None or type(process.returncode)is not int or process.returncode!=0:\n        raise ValueError('baseline_transport_unknown_raw_retained')\n    if streams[process.stderr]:raise ValueError('baseline_ssh_stderr_unknown_raw_retained')\n    return bytes(streams[process.stdout])\n"

