RECEIVER_COLLECTOR_BINDER_SOURCE='def bind_receiver_diagnostic_collector(original, terminal_parser, correlation, source):\n    """Retain only source-generated finite failed receiver diagnostics.\n    The original collector archives both streams before this classification.\n    This path never returns success, changes deadlines, or grants replay.\n    """\n    import hashlib,json,types,uuid\n    from pathlib import Path\n    from agent_tools import android_installer_component_bundle as bundle\n    if type(original)is not types.FunctionType or type(terminal_parser)is not types.FunctionType or type(source)is not bytes or type(correlation)is not str or str(uuid.UUID(correlation))!=correlation:\n        raise ValueError(\'carrier_receiver_collector_binding_invalid\')\n    def fingerprint(code):\n        return (code.co_argcount,code.co_posonlyargcount,code.co_kwonlyargcount,code.co_nlocals,code.co_stacksize,code.co_flags,code.co_code,tuple(fingerprint(x)if type(x)is types.CodeType else x for x in code.co_consts),code.co_names,code.co_varnames,code.co_freevars,code.co_cellvars,code.co_exceptiontable)\n    scope={};exec(compile(COLLECTOR_SOURCE,\'<source-bound-original-collector>\',\'exec\',dont_inherit=True),scope)\n    if original.__defaults__ is not None or original.__kwdefaults__ is not None or original.__closure__ is not None or fingerprint(original.__code__)!=fingerprint(scope[\'collect\'].__code__):\n        raise ValueError(\'carrier_receiver_collector_source_changed\')\n    prefix=b\'VPNCONTROL_COMPONENT_DIAGNOSTIC_V1 \'\n    allowed=(\'baseline_remote_collection_timeout\',\'baseline_root_stdin_write_unknown\',\'baseline_remote_collection_limit\')\n    def collect(state,credential):\n        if state.get(\'source\')!=source or type(state.get(\'request\'))is not dict or state[\'request\'].get(\'correlationId\')!=correlation:raise ValueError(\'carrier_receiver_collector_binding_invalid\')\n        try:return original(state,credential)\n        except ValueError as error:\n            if error.args!=(\'baseline_ssh_stderr_unknown_raw_retained\',):raise\n            capture=state[\'capture\'];folder=Path(capture.path)\n            def stream(name):\n                raw,pin=bundle._read(folder/(name+\'-manifest.json\'),True);manifest=json.loads(raw)\n                if type(manifest)is not dict or set(manifest)!={\'bytes\',\'sha256\',\'chunks\'}or type(manifest[\'bytes\'])is not int or not 0<=manifest[\'bytes\']<=201326592 or type(manifest[\'chunks\'])is not list or len(manifest[\'chunks\'])>384:raise error\n                parts=[]\n                for index,row in enumerate(manifest[\'chunks\']):\n                    if type(row)is not dict or set(row)!={\'name\',\'pin\'}or row[\'name\']!=name+\'-\'+str(index)+\'.private\':raise error\n                    content,actual=bundle._read(folder/row[\'name\'],True)\n                    if {key:actual[key]for key in (\'generation\',\'sha256\')}!=row[\'pin\']or len(content)>524288:raise error\n                    parts.append(content)\n                content=b\'\'.join(parts)\n                if len(content)!=manifest[\'bytes\']or hashlib.sha256(content).hexdigest()!=manifest[\'sha256\']or bundle._read(folder/(name+\'-manifest.json\'),True)!=(raw,pin):raise error\n                return content\n            err=stream(\'stderr\')\n            if not 1<=len(err)<=512 or not err.startswith(prefix)or not err.endswith(b\'\\n\')or err.count(b\'\\n\')!=1:raise error\n            try:diagnostic=json.loads(err[len(prefix):-1])\n            except (ValueError,UnicodeDecodeError):raise error\n            required={\'schema\',\'kind\',\'stage\',\'type\',\'code\',\'authorityGranted\'}\n            if type(diagnostic)is not dict or set(diagnostic)!=required or type(diagnostic[\'schema\'])is not int or diagnostic[\'schema\']!=1 or diagnostic[\'kind\']!=\'component-carrier-failure-diagnostic\'or diagnostic[\'stage\']!=\'native-collection\'or diagnostic[\'type\']!=\'ValueError\'or diagnostic[\'code\']not in allowed or diagnostic[\'authorityGranted\']is not False or err!=prefix+json.dumps(diagnostic,sort_keys=True,separators=(\',\',\':\')).encode()+b\'\\n\':raise error\n            out=stream(\'stdout\')\n            if state.get(\'source\')!=source:raise error\n            try:terminal_parser(out,state)\n            except ValueError as refusal:\n                if refusal.args!=(\'baseline_component_terminal_unknown_raw_retained\',):raise error\n            else:raise error\n            header=json.loads(bundle._read(folder/\'remote-terminal.json\',True)[0])\n            if type(header[\'sourceBytes\'])is not int or header[\'sourceBytes\']!=len(source)or header[\'sourceSha256\']!=hashlib.sha256(source).hexdigest()or header[\'failure\']!=\'ValueError\'or type(header[\'returncode\'])is not int or header[\'returncode\'] not in (-9,0,1):raise error\n            record={\'schema\':1,\'kind\':\'source-bound-receiver-finite-failure\',\'correlationId\':correlation,\'sourceSha256\':hashlib.sha256(source).hexdigest(),\'sourceBytes\':len(source),\'diagnostic\':diagnostic,\'receiverReturncode\':header[\'returncode\'],\'transportSucceeded\':True,\'closingAuthenticated\':False,\'effectOutcome\':\'unknown\',\'acceptanceComplete\':False,\'replayAllowed\':False}\n            capture.create(\'receiver-finite-failure.json\',(json.dumps(record,sort_keys=True,separators=(\',\',\':\'))+\'\\n\').encode())\n            raise ValueError(diagnostic[\'code\']) from None\n    return collect\n'
